 s+=asset('monitor-frame',...LAYOUT.monitor)+asset(state.t<.8?'screen-idle':state.t>=3.2&&state.t<9?'screen-off':state.t<11.5?'screen-running':state.t<15?'screen-review':'screen-running',...LAYOUT.screen);
